head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil00301";
scwin.otherFormObj = undefined;
scwin.pageSize = null;

// TODO Stage2: 세션 키 실환경 확인(회신 11항 · user-info 계약에 없는 키) — session.user.usrTpCd

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.pageSize = "" + dma_pageContext.get("pageSize") + "";
        scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil00301.onpageload' });
    }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_usrTpCd", fn: function(){ return ($c.session.getUserInfo("usrTpCd") === '3'); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_tgtIsurCd", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_tgtFssUnqNo", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["fssUnqNo"] ?? ""); } },
        { childId: "ipt_tgtComNm", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } },
        { childId: "ipt_tgtIsuSrtCd", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["repIsuSrtCd"] ?? ""); } },
        { childId: "ipt_tgtIsurCd_2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["isurCd"] ?? ""); } },
        { childId: "ipt_tgtFssUnqNo_2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["fssUnqNo"] ?? ""); } },
        { childId: "ipt_tgtComNm_2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } },
        { childId: "ipt_tgtComEngNm", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["comNm"] ?? ""); } },
        { childId: "ipt_tgtIsuSrtCd_2", fn: function () { return String((($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {})["repIsuSrtCd"] ?? ""); } },
        { childId: "ipt_method", fn: function () { return String((dma_pageContext.get("method") ?? "")); } },
        { childId: "ipt_disclsTitle_2", fn: function () { return String((dma_pageContext.get("disclsTitle") ?? "")); } },
        { childId: "__rb0", fn: function () { return "전체 " + String(dma_docPage.get("total")) + "건 (" + String(dma_docPage.get("currentPage")) + "/" + String(dma_docPage.get("endListPage")) + " 페이지) "; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_submit). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_goWrite();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_78_onclick
 * @description img_78 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_78_onclick = function(e){
    try {
        fn_ViewManualKeyWord(0200000015)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00301.img_78_onclick' }); }
};

/**
 * @method
 * @name img_98_onclick
 * @description img_98 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_98_onclick = async function(e){
    try {
        await scwin.searchList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00301.img_98_onclick' }); }
};

/**
 * @method
 * @name slc_pageSize_onchange
 * @description slc_pageSize 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_pageSize_onchange = async function(e){
    try {
        scwin.initPageIndex();await scwin.searchList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00301.slc_pageSize_onchange' }); }
};

/**
 * @method
 * @name grd_docPageList_oncellclick
 * @description grd_docPageList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_docPageList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_docPageList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_viewOtherForm (인자 미해석) · document.getElementById('${doc.acptNo}'+'_0_otherForm').style.display = 'none'; (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}' , '${doc.formVer}', '${doc.beforeFormVer}' , '${doc.beforeEngFormVer}', '${doc.oldFormVerUseYn}' ,'${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo }','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }','${doc.exmptObjDisclsYn  }'); (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}' , '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}' ,'${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo }','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }','${doc.exmptObjDisclsYn  }'); (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}' , '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}' ,'${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo }','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }','${doc.exmptObjDisclsYn  }'); (EL 미해석) · fn_goModifyWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}', '${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.disclsAcptTpCd}','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }' ); (EL 미해석) */

    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_docPageList.oncellclick' });
    }
};

/**
 * @method
 * @name krxpage_pagenavigator_180_onclick
 * @description krxpage_pagenavigator_180 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_180_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_goWriteReq').set('pageIndex', pi);
        await scwin.tx_fn_goWrite();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil00301.krxpage_pagenavigator_180_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_searchList
 * @description search List 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_searchList = async function () {
    const sbmOptions = {
        id: "tx_fn_searchList",
        method: "post",
        action: "",
        ref: "dma_documentWriteReq",
        target: "dlt_docPageList=body",
        isProcessMsg: false
    };
    return await $c.sbm.executeDynamic(sbmOptions);
};

/**
 * @method
 * @name tx_fn_documentWrite
 * @description document Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_documentWriteReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocumentForNewEnglishDoc",
        ref: "dma_goWriteReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["total"] != null ? rj["total"] : (rj.body && rj.body["total"]));
    if (tot != null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_180").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goModifyWrite
 * @description go Modify Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goModifyWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goModifyWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchChangeDocumentDetail",
        ref: "dma_goModifyWriteReq",
        target: "dlt_docPageList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_documentWriteReq').set('pageIndex', "1");
};

/**
 * @method
 * @name grd_docPageList_fmt_formKorNm
 * @description grd doc Page List fmt form Kor Nm 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_formKorNm = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "disclsTitle") ?? '') : '');
        if (v !== '') { return (console.error('[sdd] 미실현 라벨 갈래: formKorNm (expression)'), String(data ?? '')); }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.formKorNm" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_column6
 * @description grd doc Page List fmt column6 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_column6 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "disclsAcptTpCd") ?? '') : '');
        if (v === 'F') { return "최초"; }
        if (v === 'M') { return "정정"; }
        if (v === 'A') { return "첨부추가"; }
        if (v === 'U') { return "첨부정정"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.column6" }); return String(data ?? ''); }
};

/**
 * @method
 * @name grd_docPageList_fmt_beforeFormVerUsePurpsDsc
 * @description grd doc Page List fmt before Form Ver Use Purps Dsc 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_docPageList_fmt_beforeFormVerUsePurpsDsc = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_docPageList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "oldFormVerUseYn") ?? '') : '');
        if (v === 'Y') { return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + String((dl && dl.getCellData ? dl.getCellData(r, "beforeFormVerUsePurpsDsc") : '') ?? '') + '</a>'; }
        return '<a href="javascript:void(0)"' + (false ? ' class="lnk"' : '') + '>' + (console.error('[sdd] 미실현 라벨 갈래: beforeFormVerUsePurpsDsc (image)'), String(data ?? '')) + '</a>';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "grd_docPageList.beforeFormVerUsePurpsDsc" }); return String(data ?? ''); }
};

/**
 * @method
 * @name searchList
 * @description search List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchList = async function () {
    await scwin.tx_fn_searchList();
};

/**
 * @method
 * @name documentWrite
 * @description document Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentWrite = async function () {
    (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument';
    await scwin.tx_fn_documentWrite();
};

/**
 * @method
 * @name registerProcess
 * @description register Process 처리
 * @param {*} applNo applNo
 * @param {*} docNo docNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} method method
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method) {
    $c.util.getComponent('dma_documentWriteReq').set('applNo', applNo);
    if (applNo.length === 14) {
        await scwin.documentWrite();
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
};

/**
 * @method
 * @name registerMessage
 * @description register Message 처리
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMessage = async function (msg) {
    await $c.win.alert(msg);
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @param {*} acptNo acptNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {*} currFormVer currFormVer
 * @param {*} currEngFormVer currEngFormVer
 * @param {String} oldFormVerUseYn oldFormVerUseYn
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} rsnClssCd rsnClssCd
 * @param {String} applFormYn applFormYn
 * @param {String} ldMktTpCd ldMktTpCd
 * @param {*} inqOrgnDisclsAcptNo inqOrgnDisclsAcptNo
 * @param {*} engOrgnDisclsAcptNo engOrgnDisclsAcptNo
 * @param {String} subcomDisclsYn subcomDisclsYn
 * @param {String} disclsObjCorpIsurCd disclsObjCorpIsurCd
 * @param {String} disclsObjCorpIsurNm disclsObjCorpIsurNm
 * @param {*} disclsObjCorpFssUnqNo disclsObjCorpFssUnqNo
 * @param {String} disclsObjRepIsuSrtCd disclsObjRepIsuSrtCd
 * @param {*} comEngAbbrv comEngAbbrv
 * @param {String} exmptObjDisclsYn exmptObjDisclsYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function (acptNo, formCd, formVer, currFormVer, currEngFormVer, oldFormVerUseYn, formUpclssCd, rsnClssCd, applFormYn, ldMktTpCd, inqOrgnDisclsAcptNo, engOrgnDisclsAcptNo, subcomDisclsYn, disclsObjCorpIsurCd, disclsObjCorpIsurNm, disclsObjCorpFssUnqNo, disclsObjRepIsuSrtCd, comEngAbbrv, exmptObjDisclsYn) {
    if (await $c.win.confirm("선택하신 공시문서를  제출하려는 영문공시에 대한 국문공시로 지정하시겠습니까? 한번 지정하신 후 변경은 불가합니다.")) {
        (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocumentForNewEnglishDoc';
        $c.util.getComponent('dma_documentWriteReq').set('applNo', '' + dma_disclosureDocumentVO.get("applNo") + '');
        $c.util.getComponent("dma_documentWriteReq").set("disclsMaindocFormCd", $c.util.getComponent('ipt_formCd').getValue());
        $c.util.getComponent("dma_documentWriteReq").set("disclsMaindocFormVer", $c.util.getComponent('ipt_formVer').getValue());
        $c.util.getComponent("dma_documentWriteReq").set("formCd", $c.util.getComponent('ipt_formCd').getValue());
        $c.util.getComponent("dma_documentWriteReq").set("formVer", $c.util.getComponent('ipt_formVer').getValue());
        $c.util.getComponent("dma_documentWriteReq").set("engFormYn", 'Y');
        $c.util.getComponent("dma_documentWriteReq").set("formUpclssCd", $c.util.getComponent('ipt_formUpclssCd').getValue());
        $c.util.getComponent("dma_documentWriteReq").set("subcomDisclsYn", $c.util.getComponent('ipt_subcomDisclsYn').getValue());
        $c.util.getComponent("dma_documentWriteReq").set("engOrgnDisclsAcptNo", engOrgnDisclsAcptNo);
        $c.util.getComponent('dma_documentWriteReq').set('exmptObjDisclsYn', exmptObjDisclsYn);
        await $c.win.alert("제출하시려던 영문공시 작성화면으로 이동합니다. 이동 후 제출버튼을 눌러 계속 진행하시기 바랍니다.");
        await scwin.tx_fn_goWrite();
    } else {
        return;
    }
};

/**
 * @method
 * @name viewOtherForm
 * @description view Other Form 처리
 * @param {String} divId divId
 * @param {String} langTpCd langTpCd
 * @returns {void}
 * @hidden N
 */
scwin.viewOtherForm = function (divId, langTpCd) {
    if (scwin.otherFormObj != null && scwin.otherFormObj !== 'undefined') {
        scwin.otherFormObj.style.display = 'none';
    }
    if ($c.util.getComponent(divId + '_otherForm').getStyle('display') === 'none') {
        ($c.util.getComponent(divId + '_otherForm') && $c.util.getComponent(divId + '_otherForm').show ? $c.util.getComponent(divId + '_otherForm').show() : console.warn('[sdd] show 대상 미해결: ' + divId + '_otherForm'));
    } else {
        ($c.util.getComponent(divId + '_otherForm') && $c.util.getComponent(divId + '_otherForm').hide ? $c.util.getComponent(divId + '_otherForm').hide() : console.warn('[sdd] hide 대상 미해결: ' + divId + '_otherForm'));
    }
    scwin.otherFormObj = $c.util.getComponent(divId + '_otherForm');
};

